// Real-world math a family can do with what is already at home or in the neighborhood. Each entry names its strand
// (the same twelve keys the coach uses) and carries `facts`, small numeric claims { expr, value, show? } that the tests
// recompute independently so the numbers printed in the steps are always right. @fm2 FM-029
import { strandKey } from "./coach.js";

const build = (id, grades, minutes, strand, title, mats, steps, ask, ext, facts) => ({
  id, grades, minutes, strand,
  title: { en: title[0], es: title[1] },
  materials: { en: mats[0], es: mats[1] },
  steps: { en: steps[0], es: steps[1] },
  askThis: { en: ask[0], es: ask[1] },
  extension: { en: ext[0], es: ext[1] },
  facts,
});

