const clone = (entry) => structuredClone(entry);
const spanOf = (entry, grade) => (grade < entry.grades[0] ? entry.grades[0] - grade : grade > entry.grades[1] ? grade - entry.grades[1] : 0);

export const forGrade = (grade) => ACTIVITIES.filter((entry) => entry.grades[0] <= grade && grade <= entry.grades[1]).map(clone);

// Entries for a strand (a strand key, a strand title or a {en, es} strand) near a grade; falls back to the closest
// grade in that strand, then to any activity for the grade, so a caller always gets something to show.
export function forSkill(strand, grade) {
  const key = typeof strand === "string" && ACTIVITIES.some((entry) => entry.strand === strand) ? strand : strandKey(strand);
  const same = ACTIVITIES.filter((entry) => entry.strand === key);
  const exact = same.filter((entry) => spanOf(entry, grade) === 0);
  if (exact.length) return exact.map(clone);
  if (same.length) {
    const nearest = Math.min(...same.map((entry) => spanOf(entry, grade)));
    return same.filter((entry) => spanOf(entry, grade) === nearest).map(clone);
  }
  return forGrade(grade);
}
